 18→function resolvePlaywrightApi(candidate) {
 19→  if (!candidate) {
 20→    return null;
 21→  }
 22→
 23→  if (candidate.firefox) {
 24→    return candidate;
 25→  }
 26→
 27→  if (candidate.default) {
 28→    const resolved = resolvePlaywrightApi(candidate.default);
 29→    if (resolved) {
 30→      return resolved;
 31→    }
 32→  }
 33→
 34→  if (typeof candidate.createInProcessPlaywright === 'function') {
 35→    const resolved = withDefault(candidate, (mod) => mod.createInProcessPlaywright());
 36→    if (resolved) {
 37→      return resolved;
 38→    }
 39→  }
 40→
 41→  if (typeof candidate.createPlaywright === 'function') {
 42→    const resolved = withDefault(candidate, (mod) => mod.createPlaywright({ sdkLanguage: process.env.PW_LANG_NAME || 'javascript' }));
 43→    if (resolved && resolved.firefox) {
 44→      return resolved;
 45→    }
 46→  }
 47→
 48→  if (candidate.playwright) {
 49→    return resolvePlaywrightApi(candidate.playwright);
 50→  }
 51→
 52→  return null;
 53→}
