 55→function loadPlaywright() {
 56→  const override = process.env.CAMOUFOX_PLAYWRIGHT_JS_REQUIRE;
 57→  if (override) {
 58→    // eslint-disable-next-line global-require, import/no-dynamic-require
 59→    return require(override);
 60→  }
