125→async function run() {
126→  const rl = readline.createInterface({
127→    input: process.stdin,
128→    crlfDelay: Infinity,
129→    terminal: false,
130→  });
131→
132→  let initialized = false;
133→  let browser;
134→  let context;
135→  let page;
136→
137→  rl.on('line', async (line) => {
138→    try {
139→      if (!initialized) {
140→        const payload = decodePayload(line);
141→        if (!payload || !payload.options) {
142→          throw new Error('Missing launch options');
143→        }
144→
145→        const options = payload.options;
146→        if (options.executablePath && !fs.existsSync(options.executablePath)) {
147→          delete options.executablePath;
148→        }
149→
150→        const playwrightModule = loadPlaywright();
151→        const playwright = resolvePlaywrightApi(playwrightModule);
152→        const browserType = playwright && playwright.firefox;
153→        if (!browserType) {
154→          throw new Error('Playwright module does not expose `firefox` browser type');
155→        }
156→
157→        const stealthScript = `
158→          // Hide webdriver flag
159→          Object.defineProperty(navigator, 'webdriver', { get: () => false });
160→
161→          // Fake plugins array
162→          Object.defineProperty(navigator, 'plugins', {
163→            get: () => {
164→              const p = [
165→                { name: 'PDF Viewer', filename: 'internal-pdf-viewer', description: 'Portable Document Format' },
166→                { name: 'Chrome PDF Viewer', filename: 'internal-pdf-viewer', description: '' },
167→                { name: 'Chromium PDF Viewer', filename: 'internal-pdf-viewer', description: '' },
168→              ];
169→              p.length = 3;
170→              return p;
171→            },
172→          });
173→
174→          // Hide Playwright-specific markers
175→          delete window.__playwright;
176→          delete window.__pw_manual;
177→          delete window.__PW_inspect;
178→
179→          // Patch permissions API
180→          const origQuery = window.navigator.permissions.query.bind(window.navigator.permissions);
181→          window.navigator.permissions.query = (params) => {
182→            if (params.name === 'notifications') {
183→              return Promise.resolve({ state: Notification.permission });
184→            }
185→            return origQuery(params);
186→          };
187→
188→          // Convincing toString for overridden getters
189→          const nativeToString = Function.prototype.toString;
190→          const overrides = new Map();
191→          function mockNative(fn, nativeName) {
192→            overrides.set(fn, 'function ' + nativeName + '() { [native code] }');
193→          }
194→          Function.prototype.toString = function () {
195→            if (overrides.has(this)) return overrides.get(this);
196→            return nativeToString.call(this);
197→          };
198→          mockNative(Function.prototype.toString, 'toString');
199→        `;
200→
201→        const userDataDir = options.userDataDir;
202→        if (userDataDir) {
203→          delete options.userDataDir;
204→          context = await browserType.launchPersistentContext(userDataDir, options);
205→          await context.addInitScript(stealthScript);
206→          const pages = context.pages();
207→          page = pages.length ? pages[0] : await context.newPage();
208→        } else {
209→          browser = await browserType.launch(options);
210→          const ctx = browser.contexts()[0] || await browser.newContext();
211→          await ctx.addInitScript(stealthScript);
212→          page = ctx.pages()[0] || await ctx.newPage();
213→        }
214→        initialized = true;
215→        writeMessage({ event: 'ready' });
216→        return;
217→      }
218→
219→      const payload = decodePayload(line);
220→      if (!payload || typeof payload !== 'object') {
221→        throw new Error('Invalid command payload');
222→      }
223→
224→      const { id, action, params = {} } = payload;
225→      if (typeof id === 'undefined') {
226→        throw new Error('Command is missing id');
227→      }
228→
229→      const respond = (body) => writeMessage({ id, ...body });
230→
231→      try {
232→        let result;
233→        switch (action) {
234→          case 'goto': {
235→            const { url, waitUntil = 'domcontentloaded', waitForNetworkIdleTimeout = 15000 } = params;
236→            if (!url) {
237→              throw new Error('goto requires a url');
238→            }
239→            await page.goto(url, { waitUntil });
240→            await waitForNetworkIdle(page, waitForNetworkIdleTimeout);
241→            const [title, content] = await Promise.all([page.title(), page.content()]);
242→            result = { title, content };
243→            break;
244→          }
245→          case 'wait_for_selector': {
246→            const { selector, options = {} } = params;
247→            if (!selector) {
248→              throw new Error('wait_for_selector requires a selector');
249→            }
250→            const handle = await page.waitForSelector(selector, options);
251→            if (handle) {
252→              await handle.dispose();
253→            }
254→            result = { resolved: true };
255→            break;
256→          }
257→          case 'content': {
258→            const content = await page.content();
259→            result = { content };
260→            break;
261→          }
262→          case 'title': {
263→            const title = await page.title();
264→            result = { title };
265→            break;
266→          }
267→          case 'screenshot': {
268→            const { fullPage = false } = params;
269→            const buffer = await page.screenshot({ fullPage });
270→            const base64 = buffer.toString('base64');
271→            result = { data: base64 };
272→            break;
273→          }
274→          case 'evaluate': {
275→            const { expression, arg } = params;
276→            if (!expression || typeof expression !== 'string') {
277→              throw new Error('evaluate requires a string expression');
278→            }
279→            const pageFunction = coercePageFunction(expression);
280→            const target = pageFunction || expression;
281→            const value = arg !== undefined
282→              ? await page.evaluate(target, arg)
283→              : await page.evaluate(target);
284→            result = { value };
285→            break;
286→          }
287→          case 'close': {
288→            if (context) {
289→              await context.close();
290→              context = null;
291→            } else if (browser) {
292→              await browser.close();
293→              browser = null;
294→            }
295→            result = { closed: true };
296→            respond({ result });
297→            rl.close();
298→            return process.exit(0);
299→          }
300→          default:
301→            throw new Error(`Unknown action: ${action}`);
302→        }
303→
304→        respond({ result });
305→      } catch (error) {
306→        respond({ error: { message: error.message || String(error), name: error.name } });
307→      }
308→    } catch (fatalError) {
309→      console.error(fatalError.message || fatalError);
310→      process.exit(1);
311→    }
312→  });
313→
314→  rl.on('close', async () => {
315→    if (context) {
316→      try {
317→        await context.close();
318→      } catch (error) {
319→        // swallow
320→      }
321→    } else if (browser) {
322→      try {
323→        await browser.close();
324→      } catch (error) {
325→        // swallow
326→      }
327→    }
328→  });
329→}
