 90→VALUE build_cli_response(const char* command) {
 91→  VALUE pkgman = pkgman_module();
 92→
 93→  if (strcmp(command, "path") == 0) {
 94→    if (!NIL_P(pkgman)) {
 95→      VALUE dir = rb_funcall(pkgman, rb_intern("install_dir"), 0);
 96→      if (!NIL_P(dir)) {
 97→        VALUE result = rb_str_dup(dir);
 98→        rb_str_cat_cstr(result, "\n");
 99→        return result;
100→      }
101→    }
102→    return rb_str_new_cstr("(not configured)\n");
103→  }
104→  if (strcmp(command, "version") == 0) {
105→    if (!NIL_P(pkgman)) {
106→      VALUE ver = rb_funcall(pkgman, rb_intern("version_string"), 0);
107→      if (!NIL_P(ver)) {
108→        VALUE result = rb_str_new_cstr("Camoufox ");
109→        rb_str_append(result, ver);
110→        rb_str_cat_cstr(result, "\n");
111→        return result;
112→      }
113→    }
114→    return rb_str_new_cstr("Camoufox not installed\n");
115→  }
116→  if (strcmp(command, "fetch") == 0) {
117→    if (!NIL_P(pkgman)) {
118→      rb_funcall(pkgman, rb_intern("install"), 0);
119→      return rb_str_new_cstr("Fetch complete.\n");
120→    }
121→    return rb_str_new_cstr("Pkgman not available.\n");
122→  }
123→  if (strcmp(command, "remove") == 0) {
124→    if (!NIL_P(pkgman)) {
125→      rb_funcall(pkgman, rb_intern("remove"), 0);
126→      return rb_str_new_cstr("Remove complete.\n");
127→    }
128→    return rb_str_new_cstr("Pkgman not available.\n");
129→  }
130→  return rb_str_new_cstr("Unknown command.\n");
131→}
