22→function collectData() {
23→  return new Promise((resolve) => {
24→    let data = '';
25→    process.stdin.setEncoding('utf8');
26→
27→    process.stdin.on('data', (chunk) => {
28→      data += chunk;
29→    });
30→
31→    process.stdin.on('end', () => {
32→      const buffer = Buffer.from(data, 'base64');
33→      resolve(JSON.parse(buffer.toString()));
34→    });
35→  });
36→}
