#include <cstdlib>

namespace {

VALUE pkgman_module() {
  ID camoufox_id = rb_intern("Camoufox");
  if (!rb_const_defined(rb_cObject, camoufox_id)) {
    return Qnil;
  }

  VALUE camoufox_mod = rb_const_get(rb_cObject, camoufox_id);
  ID pkgman_id = rb_intern("Pkgman");
